import { EventEmitter } from '../mochievents/index.js';
import * as http from '../mochihttp/index.js';

function unsupported(name) {
    const err = new Error(`mochihttps: ${name} is unavailable on MochiBerry runtime`);
    err.code = 'MOCHI_UNSUPPORTED';
    return err;
}

export function request() { const req = new http.ClientRequest(); queueMicrotask(() => req.emit('error', unsupported('https.request'))); return req; }
export function get() { return request(); }
export function createServer() { throw unsupported('https.createServer'); }
export default { ...http, request, get, createServer };
